// Schema Generator Studio
function initSchemaGenerator() {
  const typeSelect = document.getElementById('schemaTypeSelect');
  const projNameInput = document.getElementById('schemaProjectName');
  const projLocationInput = document.getElementById('schemaProjectLocation');
  const projPriceInput = document.getElementById('schemaProjectPrice');
  const reraInput = document.getElementById('schemaReraNo');
  const codeOutput = document.getElementById('schemaJsonOutput');
  const copyBtn = document.getElementById('copySchemaBtn');

  const updateSchema = () => {
    const type = typeSelect ? typeSelect.value : 'RealEstateAgent';
    const name = (projNameInput && projNameInput.value) || 'Guru Punvaanii Properties';
    const loc = (projLocationInput && projLocationInput.value) || 'Anekal, Bangalore, Karnataka';
    const price = (projPriceInput && projPriceInput.value) || 'INR 35,00,000 Onwards';
    const rera = (reraInput && reraInput.value) || 'PRM/KA/RERA/1251/308/PR/200924/007089';

    let schemaObj = {};

    if (type === 'RealEstateAgent') {
      schemaObj = {
        "@context": "https://schema.org",
        "@type": "RealEstateAgent",
        "@id": "https://gurupunvaanii.com/#organization",
        "name": name,
        "url": "https://gurupunvaanii.com/",
        "logo": "https://gurupunvaanii.com/wp-content/uploads/2026/03/guru-punvaanii-logo.png",
        "description": "Premium BMRDA, BDA, and RERA-approved plotted developments and luxury villas in Karnataka.",
        "telephone": "+91-80-XXXXXXXX",
        "priceRange": price,
        "address": {
          "@type": "PostalAddress",
          "streetAddress": "Bangalore Corporate Office",
          "addressLocality": "Bengaluru",
          "addressRegion": "Karnataka",
          "addressCountry": "IN"
        },
        "geo": {
          "@type": "GeoCoordinates",
          "latitude": "12.989404",
          "longitude": "77.576850"
        }
      };
    } else if (type === 'SingleFamilyResidence') {
      schemaObj = {
        "@context": "https://schema.org",
        "@type": "SingleFamilyResidence",
        "name": name,
        "description": `Luxury climate-controlled residential villa project situated in ${loc}.`,
        "address": {
          "@type": "PostalAddress",
          "addressLocality": loc,
          "addressRegion": "Karnataka",
          "addressCountry": "IN"
        },
        "offers": {
          "@type": "Offer",
          "price": price,
          "priceCurrency": "INR",
          "availability": "https://schema.org/InStock"
        },
        "identifier": rera
      };
    } else {
      schemaObj = {
        "@context": "https://schema.org",
        "@type": "Product",
        "name": `${name} - Plotted Development`,
        "description": `BMRDA approved premium residential villa plots in ${loc}.`,
        "offers": {
          "@type": "Offer",
          "price": price,
          "priceCurrency": "INR",
          "availability": "https://schema.org/InStock"
        },
        "additionalProperty": [
          { "@type": "PropertyValue", "name": "RERA Registration", "value": rera },
          { "@type": "PropertyValue", "name": "Approval Authority", "value": "BMRDA / BDA Approved" }
        ]
      };
    }

    if (codeOutput) {
      codeOutput.innerText = JSON.stringify(schemaObj, null, 2);
    }
  };

  if (typeSelect) typeSelect.addEventListener('change', updateSchema);
  if (projNameInput) projNameInput.addEventListener('input', updateSchema);
  if (projLocationInput) projLocationInput.addEventListener('input', updateSchema);
  if (projPriceInput) projPriceInput.addEventListener('input', updateSchema);
  if (reraInput) reraInput.addEventListener('input', updateSchema);

  if (copyBtn) {
    copyBtn.addEventListener('click', () => {
      if (codeOutput) {
        navigator.clipboard.writeText(codeOutput.innerText);
        copyBtn.innerText = 'Copied!';
        setTimeout(() => copyBtn.innerText = 'Copy JSON-LD', 2000);
      }
    });
  }

  updateSchema();
  renderSchemaAuditTable();
}

// Render Schema Audit Table for all crawled pages
function renderSchemaAuditTable() {
  const tbody = document.getElementById('schemaAuditTableBody');
  if (!tbody) return;

  const renderRows = (pages) => {
    tbody.innerHTML = pages.map(p => {
      const types = p.schema_types || p.json_ld_types || [];
      const hasRealEstate = types.some(t => t.toLowerCase().includes('realestate') || t.toLowerCase().includes('residence') || t.toLowerCase().includes('product'));
      const hasAny = types.length > 0;
      
      let badgeClass = 'badge-p0';
      let statusText = 'Missing Schema';
      if (hasRealEstate) {
        badgeClass = 'badge-p3';
        statusText = 'Verified RealEstate';
      } else if (hasAny) {
        badgeClass = 'badge-p1';
        statusText = 'Generic (' + types.slice(0, 2).join(', ') + ')';
      }

      let recommendation = 'Inject RealEstateAgent & Product JSON-LD';
      if (p.url.includes('/blog/') || p.url.includes('/post-sitemap')) {
        recommendation = 'Article + FAQPage + BreadcrumbList';
      } else if (p.url.includes('plots') || p.url.includes('villas')) {
        recommendation = 'SingleFamilyResidence + Offer + RERA';
      }

      return `
        <tr>
          <td><span class="url-cell" title="${p.url}">${p.url}</span></td>
          <td>
            ${types.length ? types.map(t => `<span class="badge" style="background:rgba(124,58,237,0.1); color:var(--accent-purple); font-size:0.7rem; margin:0.1rem;">${t}</span>`).join(' ') : '<span style="color:var(--accent-red); font-size:0.75rem;">None Detected</span>'}
          </td>
          <td><span style="font-family:var(--font-mono); font-weight:600;">${types.length} Scripts</span></td>
          <td><span class="badge ${badgeClass}">${statusText}</span></td>
          <td style="color:var(--accent-cyan); font-size:0.78rem; font-weight:600;">${recommendation}</td>
        </tr>
      `;
    }).join('');
  };

  renderRows(allPages);

  const search = document.getElementById('schemaSearchInput');
  if (search) {
    search.oninput = (e) => {
      const q = e.target.value.toLowerCase();
      const filtered = allPages.filter(p => p.url.toLowerCase().includes(q) || (p.schema_types && p.schema_types.join(' ').toLowerCase().includes(q)));
      renderRows(filtered);
    };
  }

  const covBadge = document.getElementById('schemaCoverageBadge');
  if (covBadge) {
    const validCount = allPages.filter(p => (p.schema_types && p.schema_types.length > 0)).length;
    covBadge.innerText = `${validCount}/${allPages.length} URLs with Schema`;
  }
}

