// Render GSC Queries Table
function renderGSCQueriesTable(queries) {
  const tableBody = document.getElementById('trafficKeywordsTableBody');
  if (!tableBody) return;

  if (!queries || !queries.length) {
    tableBody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding:2rem; color:var(--text-muted);">No matching Google search queries found. Try a different keyword.</td></tr>`;
    return;
  }

  tableBody.innerHTML = queries.slice(0, 100).map(q => {
    let badgeClass = 'badge-status';
    let badgeText = '🎯 Organic Search';
    if (q.clicks >= 50) {
      badgeClass = 'badge-p3';
      badgeText = '🔥 High Volume';
    } else if (q.position <= 3) {
      badgeClass = 'badge-p3';
      badgeText = '🏆 Top 3 Rank';
    } else if (q.position <= 10) {
      badgeClass = 'badge-p1';
      badgeText = '⚡ 1st Page';
    } else if (q.impressions >= 5000) {
      badgeClass = 'badge-p1';
      badgeText = '👁️ High Exposure';
    }

    const cleanPage = q.page ? q.page.replace('https://gurupunvaanii.com', '') || '/' : '/';

    return `
      <tr>
        <td>
          <div style="font-weight:700; color:var(--text-main); font-size:0.88rem;">${q.query}</div>
          <small style="color:var(--text-muted); font-size:0.72rem;">Google Search Query</small>
        </td>
        <td>
          <a href="${q.page || '#'}" target="_blank" style="color:var(--accent-cyan); font-family:var(--font-mono); font-size:0.75rem; text-decoration:none; display:inline-block; max-width:240px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${cleanPage}</a>
        </td>
        <td><span style="font-family:var(--font-mono); font-weight:700; color:var(--accent-emerald);">+${q.clicks} clicks</span></td>
        <td style="font-family:var(--font-mono); font-weight:600;">${Number(q.impressions).toLocaleString()}</td>
        <td><span class="badge ${q.ctr >= 3 ? 'badge-p3' : 'badge-p1'}">${q.ctr}%</span></td>
        <td><strong style="color:var(--accent-indigo); font-size:0.95rem;">#${q.position}</strong></td>
        <td><span class="badge ${badgeClass}">${badgeText}</span></td>
      </tr>
    `;
  }).join('');
}

// Live Keyword Search Input Listener
function setupGSCKeywordSearch() {
  const searchInput = document.getElementById('gscKeywordSearchInput');
  if (!searchInput) return;

  searchInput.oninput = (e) => {
    const term = e.target.value.toLowerCase().trim();
    if (!window.CACHED_GSC_QUERIES) return;

    if (!term) {
      renderGSCQueriesTable(window.CACHED_GSC_QUERIES);
      return;
    }

    const filtered = window.CACHED_GSC_QUERIES.filter(q => 
      q.query.toLowerCase().includes(term) || 
      (q.page && q.page.toLowerCase().includes(term))
    );
    renderGSCQueriesTable(filtered);
  };
}

// Category Filter for GSC Queries
function filterGSCQueries(category) {
  if (!window.CACHED_GSC_QUERIES) return;
  
  // Update button active state
  ['All', 'Top3', 'Clicks', 'Impressions', 'Striking'].forEach(k => {
    const btn = document.getElementById(`btnFilter${k}`);
    if (btn) btn.classList.remove('active');
  });

  let filtered = window.CACHED_GSC_QUERIES;

  if (category === 'top3') {
    const btn = document.getElementById('btnFilterTop3');
    if (btn) btn.classList.add('active');
    filtered = window.CACHED_GSC_QUERIES.filter(q => q.position <= 3.0);
  } else if (category === 'clicks') {
    const btn = document.getElementById('btnFilterClicks');
    if (btn) btn.classList.add('active');
    filtered = window.CACHED_GSC_QUERIES.filter(q => q.clicks >= 10);
  } else if (category === 'impr') {
    const btn = document.getElementById('btnFilterImpressions');
    if (btn) btn.classList.add('active');
    filtered = window.CACHED_GSC_QUERIES.filter(q => q.impressions >= 5000);
  } else if (category === 'striking') {
    const btn = document.getElementById('btnFilterStriking');
    if (btn) btn.classList.add('active');
    filtered = window.CACHED_GSC_QUERIES.filter(q => q.position > 3.0 && q.position <= 10.0);
  } else {
    const btn = document.getElementById('btnFilterAll');
    if (btn) btn.classList.add('active');
  }

  renderGSCQueriesTable(filtered);
}

// Fresh Canvas Creator to avoid 0-dimension or canvas reuse conflicts
function getFreshCanvas(containerId, canvasId) {
  const container = document.getElementById(containerId);
  if (container) {
    container.innerHTML = `<canvas id="${canvasId}" height="260" style="display:block; width:100%; height:260px;"></canvas>`;
  }
  return document.getElementById(canvasId);
}

// Render Traffic & Keyword Charts with Live GSC & GA4 Data
function renderTrafficCharts() {
  if (typeof Chart === 'undefined') return;

  const cfg = TRAFFIC_TIMEFRAME_CONFIG[currentTrafficTimeframe] || TRAFFIC_TIMEFRAME_CONFIG['28d'];
  let chartLabels = cfg.chartLabels;
  let chartVisits = cfg.visitsData;
  let chartKw = cfg.kwData;

  if (window.CACHED_GSC_DATA && Array.isArray(window.CACHED_GSC_DATA.daily_trends) && window.CACHED_GSC_DATA.daily_trends.length) {
    const daily = window.CACHED_GSC_DATA.daily_trends;
    if (currentTrafficTimeframe === '7d') {
      const slice7 = daily.slice(-7);
      chartLabels = slice7.map(d => d.date.split('-').slice(1).join('/'));
      chartVisits = slice7.map(d => d.clicks);
      chartKw = slice7.map(d => Math.round(d.impressions / 100));
    } else if (currentTrafficTimeframe === '28d') {
      const slice28 = daily.slice(-28);
      chartLabels = slice28.map(d => d.date.split('-').slice(1).join('/'));
      chartVisits = slice28.map(d => d.clicks);
      chartKw = slice28.map(d => Math.round(d.impressions / 100));
    }
  }

  // 1. Organic Traffic Line Chart
  const canvas1 = getFreshCanvas('trafficForecastContainer', 'chartTrafficForecast');
  if (canvas1) {
    if (trafficForecastChartInstance) {
      try { trafficForecastChartInstance.destroy(); } catch(e){}
      trafficForecastChartInstance = null;
    }
    const ctx1 = canvas1.getContext('2d');
    trafficForecastChartInstance = new Chart(ctx1, {
      type: 'line',
      data: {
        labels: chartLabels,
        datasets: [
          {
            label: 'Real Google Clicks',
            data: chartVisits,
            borderColor: '#0284c7',
            backgroundColor: 'rgba(2, 132, 199, 0.12)',
            fill: true,
            tension: 0.35,
            pointRadius: 4,
            pointHoverRadius: 6,
            pointBackgroundColor: '#0284c7'
          },
          {
            label: 'Impressions (÷100)',
            data: chartKw,
            borderColor: '#10b981',
            borderDash: [5, 5],
            fill: false,
            tension: 0.3,
            pointRadius: 3
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 350 },
        plugins: {
          legend: { position: 'top', labels: { boxWidth: 12, font: { size: 11, family: 'Inter, sans-serif' } } },
          tooltip: { mode: 'index', intersect: false }
        },
        scales: {
          y: { beginAtZero: false, grid: { color: 'rgba(100, 116, 139, 0.12)' } },
          x: { grid: { display: false } }
        }
      }
    });
  }

  // 2. Acquisition Channels Bar Chart
  const canvas2 = getFreshCanvas('trafficDistributionContainer', 'chartKeywordDistribution');
  if (canvas2) {
    if (trafficDistributionChartInstance) {
      try { trafficDistributionChartInstance.destroy(); } catch(e){}
      trafficDistributionChartInstance = null;
    }
    const ctx2 = canvas2.getContext('2d');
    const ga4 = window.CACHED_GA4_DATA;
    let barLabels = ['Top 1-3', 'Top 4-10', 'Top 11-20', 'Top 21-50', 'Top 51-100'];
    let barData = [38, 90, 185, 340, 587];
    let barColors = ['#10b981', '#06b6d4', '#6366f1', '#f59e0b', '#64748b'];

    if (ga4 && ga4.channels && ga4.channels.length) {
      barLabels = ga4.channels.map(c => c.channel);
      barData = ga4.channels.map(c => c.sessions);
      barColors = ['#10b981', '#06b6d4', '#6366f1', '#f59e0b', '#ec4899', '#8b5cf6', '#14b8a6', '#64748b'].slice(0, ga4.channels.length);
    }

    trafficDistributionChartInstance = new Chart(ctx2, {
      type: 'bar',
      data: {
        labels: barLabels,
        datasets: [{
          label: ga4 && ga4.channels ? 'GA4 Real Sessions' : 'Keywords Count',
          data: barData,
          backgroundColor: barColors,
          borderRadius: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 350 },
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              label: (ctx) => ` Sessions: ${ctx.parsed.y.toLocaleString()}`
            }
          }
        },
        scales: {
          y: { beginAtZero: true, grid: { color: 'rgba(100, 116, 139, 0.12)' } },
          x: { grid: { display: false } }
        }
      }
    });
  }
}

